class Solution {
    struct DSU {
        vector<int> p,sz;
        DSU(int n):p(n),sz(n,1){iota(p.begin(),p.end(),0);}
        int find(int x){return p[x]==x?x:p[x]=find(p[x]);}
        void unite(int a,int b){a=find(a);b=find(b);if(a!=b){if(sz[a]<sz[b])swap(a,b);p[b]=a;sz[a]+=sz[b];}}
    };
public:
    vector<int> groupStrings(vector<string>& words) {
        int n=words.size();DSU d(n);
        unordered_map<int,int> exact,deleted;
        vector<int> masks(n);
        for(int i=0;i<n;++i) {
            int mask=0;for(char c:words[i]) mask|=1<<(c-'a');masks[i]=mask;
            if(exact.count(mask)) d.unite(i,exact[mask]);else exact[mask]=i;
        }
        for(int i=0;i<n;++i) {
            int mask=masks[i];
            for(int b=0;b<26;++b) {
                int other=mask^(1<<b);
                auto it=exact.find(other);
                if(it!=exact.end()) d.unite(i,it->second);
                if(mask&(1<<b)) {
                    auto jt=deleted.find(other);
                    if(jt!=deleted.end()) d.unite(i,jt->second);
                    else deleted[other]=i;
                }
            }
        }
        int groups=0,biggest=0;
        for(int i=0;i<n;++i) if(d.find(i)==i) {++groups;biggest=max(biggest,d.sz[i]);}
        return {groups,biggest};
    }
};
